/**
 * Normaliza el lead que llega del endpoint de la web.
 *
 * El email es la clave de deduplicacion, asi que se normaliza aqui y no en
 * cada sitio que lo use: minusculas y sin espacios. Dos personas que escriban
 * "Ana@Example.com " y "ana@example.com" son la misma.
 *
 * Nada de lo que llega se da por bueno sin mirar: si falta el consentimiento
 * o el email, se corta aqui. El endpoint ya lo valida, pero este webhook es
 * alcanzable por su cuenta y no puede fiarse de quien le llame.
 */
const body = $json.body ?? $json;

const email = String(body?.contact?.email ?? "").trim().toLowerCase();
if (!email) {
  throw new Error("Lead sin email: no hay clave de deduplicacion.");
}
if (body?.consent?.accepted !== true) {
  throw new Error("Lead sin consentimiento aceptado: no se guarda.");
}

const txt = (value, max = 2000) => String(value ?? "").slice(0, max);

return [{
  json: {
    databaseId: $('Configuracion').first().json.leadsDatabaseId,
    email,
    name: txt(body?.contact?.name, 200) || email,
    phone: txt(body?.contact?.phone, 50),
    reason: txt(body?.reason),
    projectName: txt(body?.project?.name, 200),
    consentVersion: txt(body?.consent?.version, 40),
    consentAt: txt(body?.consent?.acceptedAt, 40),
    pageUrl: txt(body?.attribution?.pageUrl, 2000),
    locale: txt(body?.attribution?.locale, 10),
    utmSource: txt(body?.attribution?.utm_source, 200),
    utmMedium: txt(body?.attribution?.utm_medium, 200),
    utmCampaign: txt(body?.attribution?.utm_campaign, 200),
    utmTerm: txt(body?.attribution?.utm_term, 200),
    utmContent: txt(body?.attribution?.utm_content, 200),
    correlationId: txt(body?.correlationId, 60),
    receivedAt: new Date().toISOString(),
  },
}];

/**
 * Decide si crear o actualizar, y prepara las propiedades de Notion.
 *
 * La busqueda anterior devuelve como mucho una pagina. Si la hay, este email
 * ya escribio antes: se conserva lo que ya constaba y se suma el envio nuevo.
 *
 * El motivo NO se pisa: se apila debajo del anterior con su fecha. Perder por
 * que escribio alguien la primera vez, para quedarse solo con la ultima frase,
 * seria tirar justo el contexto que hace util un lead repetido.
 */
const lead = $('Normalizar').first().json;
const found = $json.results ?? [];
const existing = found.length > 0 ? found[0] : null;

const rich = (value) => (value ? [{ text: { content: String(value).slice(0, 2000) } }] : []);

let reason = lead.reason;
let sends = 1;

if (existing) {
  const previous = (existing.properties?.Motivo?.rich_text ?? [])
    .map((r) => r.plain_text ?? "")
    .join("");
  sends = (existing.properties?.["Envios"]?.number ?? existing.properties?.["Envíos"]?.number ?? 1) + 1;
  if (previous && reason) {
    reason = `${previous}\n\n--- ${lead.receivedAt} ---\n${reason}`.slice(-2000);
  } else if (previous) {
    reason = previous;
  }
}

const properties = {
  "Nombre": { title: [{ text: { content: lead.name.slice(0, 200) } }] },
  "Email": { email: lead.email },
  "Teléfono": lead.phone ? { phone_number: lead.phone } : { phone_number: null },
  "Motivo": { rich_text: rich(reason) },
  "Proyecto": { rich_text: rich(lead.projectName) },
  "Consentimiento": { checkbox: true },
  "Fecha de consentimiento": { date: lead.consentAt ? { start: lead.consentAt } : null },
  "Versión del texto aceptado": { rich_text: rich(lead.consentVersion) },
  "Página": { url: lead.pageUrl || null },
  "Idioma": { rich_text: rich(lead.locale) },
  "UTM Source": { rich_text: rich(lead.utmSource) },
  "UTM Medium": { rich_text: rich(lead.utmMedium) },
  "UTM Campaign": { rich_text: rich(lead.utmCampaign) },
  "UTM Term": { rich_text: rich(lead.utmTerm) },
  "UTM Content": { rich_text: rich(lead.utmContent) },
  "Correlation ID": { rich_text: rich(lead.correlationId) },
  "Envíos": { number: sends },
  "Recibido": { date: { start: lead.receivedAt } },
};

// El estado solo se pone al crear: si alguien ya lo movio a "Contactado",
// un segundo envio no puede devolverlo a "Nuevo".
if (!existing) {
  properties["Estado"] = { select: { name: "Nuevo" } };
}

return [{
  json: {
    exists: Boolean(existing),
    pageId: existing?.id ?? null,
    databaseId: lead.databaseId,
    correlationId: lead.correlationId,
    properties,
  },
}];
